import { type Amqp1Dot0ReconnectOptions } from './Amqp1Dot0ReconnectOptions.js';
import { type Amqp1Dot0SaslOptions } from './Amqp1Dot0SaslOptions.js';
import { type Amqp1Dot0TlsOptions } from './Amqp1Dot0TlsOptions.js';

export interface Amqp1Dot0ConnectionOptions {
  readonly channelMax?: number;
  /**
   * Container id sent in the open frame. Generated by default.
   */
  readonly containerId?: string;
  readonly host: string;
  /**
   * Idle timeout, in milliseconds, announced to the peer.
   */
  readonly idleTimeout?: number;
  readonly maxFrameSize?: number;
  /**
   * Defaults to 5672.
   */
  readonly port?: number;
  /**
   * Defaults to `true`: reconnect with the default backoff.
   */
  readonly reconnect?: boolean | Amqp1Dot0ReconnectOptions;
  /**
   * No SASL layer is negotiated by default.
   */
  readonly sasl?: Amqp1Dot0SaslOptions;
  /**
   * Maximum unsettled deliveries buffered for the session. Defaults to 2048.
   */
  readonly sessionBufferSize?: number;
  /**
   * Connects over TLS when set.
   */
  readonly tls?: Amqp1Dot0TlsOptions;
  /**
   * Virtual host, sent as the open frame `hostname`. Defaults to the host.
   */
  readonly virtualHost?: string;
}
